mapper.select:
SELECT wmrs.id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, db.name AS moduleStatusName FROM work_menu wm LEFT JOIN work_menu_ref_status wmrs ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value"
AND wm.sys_classify = #{sysClassify}
ORDER BY wm.sys_classify,wm.id

SELECT wm.id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, '' AS moduleStatusName FROM work_menu wm
AND wm.sys_classify = #{sysClassify}
ORDER BY sys_classify,wm.id

SELECT wm.id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, wm.module_code AS moduleCode, db.name AS moduleStatusName, wmrs.module_status AS moduleStatus, wmrs.module_url AS moduleUrl, wmrs.module_param AS moduleParam FROM work_option wo LEFT JOIN work_menu_ref_status wmrs ON wo.work_menu_id = wmrs.menu_id LEFT JOIN work_menu wm ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" WHERE wo.type = '1'
AND wo.option_user_id = #{optionUserId}
ORDER BY wm.sys_classify,wm.id

SELECT wm.id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, wmrs.module_url AS moduleUrl, wmrs.module_param AS moduleParam FROM work_option wo LEFT JOIN work_menu_ref_status wmrs ON wo.work_menu_id = wmrs.menu_id LEFT JOIN work_menu wm ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" WHERE wo.type = '2'
AND wo.option_user_id = #{optionUserId}
ORDER BY wm.sys_classify,wm.id

SELECT COUNT(*), pt.phase_name AS stageName FROM project_task pt INNER JOIN project_info pi ON pt.product_id = pi.product_id AND pi.is_deleted = FALSE LEFT JOIN project_phase pp ON pt.phase_id = pp."id" AND pt.is_deleted = FALSE WHERE pi.project_status NOT IN (3) AND pp.is_deleted = FALSE AND pt.product_id NOT IN (SELECT product_id FROM product_archive WHERE is_deleted = FALSE)
AND pt.charge_id = #{optionUserId}
GROUP BY pt.phase_name , pp.is_deleted
